const rawFindings = $.Steps.Query_Findings.data || [];

$.Helpers.setVariable('raw_findings_count', rawFindings.length);

const structuredFindings = rawFindings.map(function(row) {
  return {
    finding_id: row.finding_id ? String(row.finding_id).trim() : '',
    resource_id: row.resource_id ? String(row.resource_id).trim() : '',
    hostname: row.resource_name ? String(row.resource_name).trim() : '',
    environment: 'poc',
    severity: row.severity ? String(row.severity).toLowerCase().trim() : '',
    cve_id: row.cve_id ? String(row.cve_id).trim() : '',
    package_name: row.package_name ? String(row.package_name).trim() : '',
    installed_version: row.installed_version ? String(row.installed_version).trim() : '',
    fixed_version: row.fixed_version ? String(row.fixed_version).trim() : '',
    advisory_id: row.advisory_id ? String(row.advisory_id).trim() : '',
    finding_status: row.status ? String(row.status).toLowerCase().trim() : '',
    runtime_active: row.runtime_active === true || row.runtime_active === 'true'
  };
});

return structuredFindings;

const findings = $.Steps.Build_Findings.data || [];

const scored = findings.map(function(f) {
  var score = 0;
  var sev = (f.severity || '').toLowerCase();
  if (sev === 'critical') score += 3;
  else if (sev === 'high') score += 2;
  if (f.runtime_active === true) score += 2;
  if (f.fixed_version && f.fixed_version !== '') score += 1;
  return Object.assign({}, f, { priority_score: score });
});

scored.sort(function(a, b) { return b.priority_score - a.priority_score; });

return scored;

const findings = $.Steps.Prioritize_Findings.data || [];
const top = findings.slice(0, 1);
$.Helpers.setVariable('total_findings_count', top.length);
return top;

const findings = $.Steps.Select_Top_Findings.data || [];
if (findings.length === 0) {
  throw new Error('NO_FINDINGS: No prioritized findings requiring action. This is a normal business outcome.');
}
return findings;

const finding = $.Current.Value;
const reasons = [];

const requiredFields = ['finding_id', 'hostname', 'environment', 'severity', 'cve_id', 'package_name', 'installed_version', 'advisory_id', 'finding_status', 'fixed_version'];
for (var i = 0; i < requiredFields.length; i++) {
  var field = requiredFields[i];
  if (!finding[field] || finding[field] === '') {
    reasons.push('Missing or empty required field: ' + field);
  }
}

if (reasons.length > 0) {
  throw new Error('Data validation failed: ' + reasons.join(', '));
}

return { passed: true, reasons: [], finding: finding };

const validationResult = $.Steps.Validate_Finding.data;
const finding = validationResult && validationResult.finding;
const policyChecks = [];

if (!validationResult || !validationResult.passed) {
  policyChecks.push('Data validation did not pass');
}
if (!finding || finding.environment !== 'poc') {
  policyChecks.push('Environment must be poc, got: ' + (finding ? finding.environment : 'unknown'));
}
var severity = finding && finding.severity ? finding.severity.toLowerCase() : '';
if (severity !== 'critical' && severity !== 'high') {
  policyChecks.push('Severity must be critical or high, got: ' + severity);
}
if (!finding || finding.finding_status !== 'open') {
  policyChecks.push('Finding status must be open, got: ' + (finding ? finding.finding_status : 'unknown'));
}
if (!finding || !finding.fixed_version || finding.fixed_version.trim() === '') {
  policyChecks.push('Fixed version must exist and be non-empty');
}

if (policyChecks.length > 0) {
  throw new Error('Remediation policy enforcement failed: ' + policyChecks.join('; '));
}

return validationResult;

const liveStatus = $.Steps.Check_Already_Remediated.attributes.status;
const finding = $.Steps.Validate_Finding.data.finding;

if (liveStatus === 'resolved' || liveStatus === 'auto_closed') {
  throw new Error('ALREADY_REMEDIATED: Finding is already in status: ' + liveStatus + '. Skipping to avoid duplicate remediation.');
}

return finding;

