const jobStatus = $.Steps.Get_AAP_Job_Status.body.status;
const jobId = $.Steps.Get_AAP_Job_Status.body.id;

const terminalFailures = ['failed', 'error', 'canceled', 'cancel_request'];
if (terminalFailures.indexOf(jobStatus) !== -1) {
  throw new Error('AAP job reached terminal failure state: ' + jobStatus + ' (Job ID: ' + jobId + '). Manual investigation required.');
}

if (jobStatus === 'successful') {
  return { status: 'successful', jobId: jobId };
}

return { status: jobStatus, jobId: jobId };

const totalReturned = $.Steps.Validate_Operational_Health.total_returned;
const hostList = $.Steps.Validate_Operational_Health.host_list || [];

if (!totalReturned || totalReturned === 0) {
  throw new Error('Host is not reporting to Datadog: no hosts found');
}

const host = hostList[0];
if (!host || host.up !== true) {
  throw new Error('Host is down. up=' + (host ? host.up : 'undefined'));
}

return {
  hostname: host.name,
  up: host.up,
  agent_version: host.meta && host.meta.agent_version ? host.meta.agent_version : 'unknown',
  total_returned: totalReturned,
  status: 'healthy'
};

const status = $.Steps.Check_Vulnerability_Status.attributes.status;
const findingId = $.Steps.Check_Vulnerability_Status.attributes.finding_id;

if (status === 'resolved') {
  throw new Error('FINDING_RESOLVED: Vulnerability confirmed remediated. Finding ID: ' + findingId);
}

if (status === 'open' || status === 'in-progress' || status === 'muted') {
  return { outcome: 'pending_rescan', status: status, finding_id: findingId };
}

return { outcome: 'unexpected_status', status: status, finding_id: findingId };

